/**
 * The illustrations behind the heading of some section pages: a picture of the section's place, faded into the band
 * (the user, 28/10/2026, on marketing's brief). Decorative, generated by AI, which the band says beside it. Not on the
 * home page, which shows the news of the moment at once. On no page while Météo-France's vigilance is orange or red, a
 * cyclone alert is in force or announced, or the volcano is in alert: a calm picture would contradict the source. Not
 * written either when the browser asks to save data (`Save-Data: on`). The files: scripts/build-fonds.py.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import type { Alerte } from "./data.js";
import files from "./fonds.json" with { type: "json" };

/**
 * Each page's picture, by the name of its file; its place is the section's, never the whole island. `y`: where its
 * subject is, in % from the top, for wide screens, where the band shows only a thin strip of it.
 */
export const FONDS: Record<string, { nom: keyof typeof files; y: number }> = {
  "/meteo": { nom: "fond-meteo-cote-hauts", y: 30 },
  "/randonnees": { nom: "randonneur-maido", y: 67 },
  "/trafic": { nom: "trafic-route-littoral", y: 61 },
  "/evenements": { nom: "evenements-kiosque", y: 57 },
  "/emploi": { nom: "emploi-metiers-reunion", y: 45 },
  "/mer": { nom: "mer-lagon-ermitage", y: 60 },
};

/**
 * Behind the band's text, over its upper 220 px (300 on wide screens), never adding height: framed on its upper third
 * on a phone, on its subject on wider screens, faded out by a mask, which works on any background. Dimmed so that the
 * band's light text keeps a contrast of at least 4.5:1 where the picture is brightest. The mention at the top right,
 * like a photo credit, in the band's brightest text: the picture under it is not dimmed by any fade. Not printed.
 */
export const FOND_CSS = `
.band>.fond{position:absolute;top:0;left:0;width:100%;height:220px;object-fit:cover;object-position:50% 25%;opacity:.35;pointer-events:none;
-webkit-mask-image:linear-gradient(to bottom,#000 0%,rgb(0 0 0/.55) 45%,transparent 100%);mask-image:linear-gradient(to bottom,#000 0%,rgb(0 0 0/.55) 45%,transparent 100%)}
@media (min-width:48rem){.band>.fond{height:300px;object-position:50% var(--y)}}
.fond-ia{position:absolute;top:.4rem;right:16px;margin:0;font-size:12px;line-height:1.2;color:var(--on-night)}
@media print{.band>.fond,.fond-ia{display:none}}
`.replace(/\n/g, "");

/** The brand kit's words, beside every picture made by AI. */
export const MENTION = "Illustration générée par IA";

const sansFond = new AsyncLocalStorage<boolean>();

/** Runs `fn` with the pages it builds left without their picture when `request` asks to save data. */
export const withSaveData = <T>(request: Request, fn: () => T): T => sansFond.run(request.headers.get("save-data")?.trim().toLowerCase() === "on", fn);

/** Whether the vigilance or the volcano rules out every picture: orange or red, any cyclone alert, the volcano's alert. */
export const enAlerte = (alerte: Alerte | undefined, volcan: boolean): boolean => volcan || (!!alerte && ("cyclone" in alerte.court || alerte.couleur >= 3));

/**
 * The picture behind the band of the page at `path` and its mention, or nothing. On a phone, half its definition: the
 * picture is faded and dimmed, and the lighter file leaves the page's stylesheet and font their bandwidth.
 */
export function fond(path: string, alerte: Alerte | undefined, volcan: boolean): string {
  const fond = FONDS[path];
  if (!fond || sansFond.getStore() || enAlerte(alerte, volcan)) return "";
  const f = files[fond.nom];
  return `<img class="fond" style="--y:${fond.y}%" src="/fonds/${f["480"]}" srcset="/fonds/${f["480"]} 480w, /fonds/${f["1024"]} 1024w" sizes="(min-width: 48rem) 100vw, 50vw" alt="" decoding="async" fetchpriority="low"><p class="fond-ia">${MENTION}</p>`;
}
